#!/usr/bin/env python3
import base64,gzip,json,pathlib
PAYLOAD=r''''''
raw=gzip.decompress(base64.b64decode(''.join(PAYLOAD.split())))
obj=json.loads(raw.decode('utf-8'))
assert obj['row_count']==100
assert len(obj['rows'])==100
assert len({r['region_slug'] for r in obj['rows']})==100
assert all(r['landing_eligibility']=='ELIGIBLE_AFTER_SLUG_QA' for r in obj['rows'])
path=pathlib.Path(__file__).resolve().parents[1]/'stage4_localities_100_v1.json'
path.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'status':'PASS','rows':len(obj['rows']),'sidos':len(obj['coverage']['sido_counts']),'unique_signatures':obj['coverage']['unique_variation_signatures']},ensure_ascii=False))
